#!/usr/bin/env python3
"""
Automated Policy Document Extraction Script
Queries public government APIs and tracks changes over time.
"""

import json
import os
import time
from datetime import datetime
from typing import Dict, List, Any
import requests
from dataclasses import dataclass, asdict
import yaml


@dataclass
class PolicyDocument:
    """Data structure for storing policy document metadata."""
    title: str
    url: str
    document_id: str
    agency: str
    publication_date: str
    summary: str
    archived: bool = False
    archived_date: str = None


class PolicyDataExtractor:
    """Main class for extracting and managing policy documents from government APIs."""

    def __init__(self, api_config_path: str = None, export_path: str = '/home/user/project/policy_data_export.json'):
        self.api_config = self._load_config(api_config_path)
        self.export_path = export_path if export_path.endswith('.json') else export_path + '.json'
        self.last_run_export = None
        self.seen_ids = set()  # To track changes over time

    def _load_config(self, config_path: str) -> Dict:
        """Load API configuration from YAML file or use defaults."""
        if config_path and os.path.exists(config_path):
            with open(config_path, 'r') as f:
                return yaml.safe_load(f)
        return self._get_default_config()

    def _get_default_config(self) -> Dict:
        """Return default API configuration for common government sources."""
        return {
            'data_gov': {
                'base_url': 'https://api.data.gov',
                'endpoints': {
                    'recent': '/catalogue/search/api?sort_direction=DESC&sort_field=updateDate&results_per_page=50'
                },
                'headers': {'User-Agent': 'PolicyResearcher/1.0'}
            },
            'regulations_gov': {
                'base_url': 'https://www.regulations.gov',
                'endpoint': '/search.json?limit=50&result_type=most_recent',
                'headers': {'User-Agent': 'PolicyResearcher/1.0'}
            },
            'scheduled_tasks': [
                {'source': 'data_gov', 'interval_hours': 24},
                {'source': 'regulations_gov', 'interval_hours': 12}
            ],
            'export_path': self.export_path
        }

    def extract(self, source: str) -> List[PolicyDocument]:
        """Extract policy documents from a specified government API source."""
        if source not in self.api_config:
            print(f"Unknown source: {source}")
            return []

        config = self.api_config[source]
        all_documents = []

        try:
            endpoint = config['endpoints']['recent'] if 'recent' in config['endpoints'] else config['endpoint']
            params = endpoint.split('?')[1] if '?' in endpoint else {}

            response = requests.get(
                f"{config['base_url']}{endpoint}",
                headers=config.get('headers', {}),
                params=params,
                timeout=30
            )
            response.raise_for_status()
            data = response.json()

            seen_ids = set()
            for item in self._map_api_to_docs(data, config):
                obj_id = self._get_doc_id(item)
                if obj_id and obj_id not in seen_ids:
                    seen_ids.add(obj_id)
                    # Track new documents
                    if obj_id not in self.seen_ids:
                        self.seen_ids.add(obj_id)
                        all_documents.append(item)
        except Exception as e:
            print(f"Error fetching from {source}: {e}")
            return []

        return all_documents

    def save(self, documents: List[PolicyDocument], format: str = 'json'):
        """Save extracted documents to a structured file."""
        timestamp = datetime.now().isoformat()

        output = {
            'export_timestamp': timestamp,
            'record_count': len(documents),
            'documents': [
                {
                    'title': d.title,
                    'url': d.url,
                    'document_id': d.document_id,
                    'agency': d.agency,
                    'publication_date': d.publication_date,
                    'summary': d.summary.replace('\n', ' ').rstrip(),
                    'archived': d.archived,
                    'archived_date': d.archived_date
                }
                for d in documents
            ]
        }

        with open(self.export_path, 'w') as f:
            json.dump(output, f, indent=2, default=str)

        self.last_run_export = timestamp
        print(f"Saved {len(documents)} documents to {self.export_path}")

    def run_schedule(self, schedule: List[Dict] = None):
        """Run extraction according to a schedule."""
        if schedule is None:
            schedule = self.api_config.get('scheduled_tasks', [])

        while True:
            for task in schedule:
                source = task.get('source')
                interval = task.get('interval_hours', 24)
                print(f"Running extraction for {source}...")
                docs = self.extract(source)
                if docs:
                    self.save(docs)

            print(f"Waiting {interval} hours...")
            time.sleep(interval * 3600)

    def _map_api_to_docs(self, data: Any, config: Dict) -> List[PolicyDocument]:
        """Map API response data to PolicyDocument objects."""
        docs = []
        if isinstance(data, dict):
            if 'records' in data:
                items = data['records']
            elif 'data' in data:
                items = data['data']
            elif 'results' in data:
                items = data['results']
            else:
                items = [data]
        elif isinstance(data, list):
            items = data
        else:
            return []

        for item in items:
            doc = PolicyDocument(
                title=self._get_field(item, ['title', 'name']),
                url=self._get_field(item, 'path') or self._get_field(item, 'accession_number') or '',
                document_id=self._get_field(item, 'identifier') or self._get_field(item, 'accession_number') or '',
                agency=self._get_field(item, 'publisher', 'name') or self._get_field(item, 'agencies', 0, 'agency_desc') or 'Unknown',
                publication_date=self._get_field(item, 'datePosted') or self._get_field(item, 'updated_at') or '',
                summary=self._get_field(item, 'description', '')[:500].replace('\n', ' ').strip()[:500]
            )
            docs.append(doc)

        return docs

    def _get_field(self, obj: Any, *keys) -> Any:
        """Navigate nested dictionaries/lists to get a field value."""
        if not keys:
            return None
        value = obj
        for key in keys:
            if isinstance(key, int):
                if isinstance(value, list) and key < len(value):
                    value = value[key]
                else:
                    return None
            else:
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    return None
        return value

    def _get_doc_id(self, doc: PolicyDocument) -> str:
        return doc.document_id


if __name__ == "__main__":
    extractor = PolicyDataExtractor()

    # Example single source extraction
    docs = extractor.extract('data_gov')
    if docs:
        extractor.save(docs)

    # Example scheduled execution (uncomment to run)
    # extractor.run_schedule()

    print("Script executed successfully.")

