        print(f"Saved {len(documents)} documents to {self.export_path}")

    def run_schedule(self, schedule: List[Dict] = None):
        """Run extraction according to a schedule."""
        if schedule is None:
            schedule = self.api_config.get('scheduled_tasks', [])

        while True:
            for task in schedule:
                source = task.get('source')
                interval = task.get('interval_hours', 24)
                print(f"Running extraction for {source}...")
                docs = self.extract(source)
                if docs:
                    self.save(docs)

            print(f"Waiting {interval} hours...")
            time.sleep(interval * 3600)

    def _map_api_to_docs(self, data: Any, config: Dict) -> List[PolicyDocument]:
        """Map API response data to PolicyDocument objects."""
        docs = []
        if isinstance(data, dict):
            if 'records' in data:
                items = data['records']
            elif 'data' in data:
                items = data['data']
            elif 'results' in data:
                items = data['results']
            else:
                items = [data]
        elif isinstance(data, list):
            items = data
        else:
            return []

        for item in items:
            doc = PolicyDocument(
                title=self._get_field(item, ['title', 'name']),
                url=self._get_field(item, 'path') or self._get_field(item, 'accession_number') or '',
                document_id=self._get_field(item, 'identifier') or self._get_field(item, 'accession_number') or '',
                agency=self._get_field(item, 'publisher', 'name') or self._get_field(item, 'agencies', 0, 'agency_desc') or 'Unknown',
                publication_date=self._get_field(item, 'datePosted') or self._get_field(item, 'updated_at') or '',
                summary=self._get_field(item, 'description', '')[:500].replace('\n', ' ').strip()[:500]
            )
            docs.append(doc)

        return docs

    def _get_field(self, obj: Any, *keys) -> Any:
        """Navigate nested dictionaries/lists to get a field value."""
        if not keys:
            return None
        value = obj
        for key in keys:
            if isinstance(key, int):
                if isinstance(value, list) and key < len(value):
                    value = value[key]
                else:
                    return None
            else:
                if isinstance(value, dict) and key in value:
                    value = value[key]
                else:
                    return None
        return value

    def _get_doc_id(self, doc: PolicyDocument) -> str:
        return doc.document_id


