        salt = bytes.fromhex(user_data["salt"])
        hashed_pw = self.password_handler.hash_password(password, salt)

        if hashed_pw != user_data["password_hash"]:
            return {"success": False, "error": "Invalid credentials"}

        session_id = self.sessions.create_session(username)
        return {"success": True, "session_id": session_id, "username": username}

    def validate_session(self, session_id: str) -> Dict[str, Any]:
        session_info = self.sessions.validate_session(session_id)
        if session_info:
            return {"success": True, "user_id": session_info["user_id"]}
        return {"success": False, "error": "Invalid or expired session"}

    def logout(self, session_id: str) -> Dict[str, Any]:
        if self.sessions.logout(session_id):
            return {"success": True, "message": "Logged out successfully"}
        return {"success": False, "error": "Session not found"}

